import{_ as a,H as s,f as l,i as n}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"24 | 建立学习框架：用AI快速拆解学习HermesAgent","description":"","frontmatter":{},"headers":[{"level":2,"title":"方法论：让 AI 帮你建立顶层认知","slug":"方法论-让-ai-帮你建立顶层认知","link":"#方法论-让-ai-帮你建立顶层认知","children":[{"level":3,"title":"学习前的一些想法","slug":"学习前的一些想法","link":"#学习前的一些想法","children":[]},{"level":3,"title":"顶层认知，要有自己的拆解框架","slug":"顶层认知-要有自己的拆解框架","link":"#顶层认知-要有自己的拆解框架","children":[]},{"level":3,"title":"带着任务去问，而不是裸问","slug":"带着任务去问-而不是裸问","link":"#带着任务去问-而不是裸问","children":[]}]},{"level":2,"title":"三个提示词，摸清楚 Hermes 大体框架","slug":"三个提示词-摸清楚-hermes-大体框架","link":"#三个提示词-摸清楚-hermes-大体框架","children":[{"level":3,"title":"提示词一：它是什么 + 它的内部机制","slug":"提示词一-它是什么-它的内部机制","link":"#提示词一-它是什么-它的内部机制","children":[]},{"level":3,"title":"提示词二：它能做什么","slug":"提示词二-它能做什么","link":"#提示词二-它能做什么","children":[]},{"level":3,"title":"提示词三：它怎么扩展","slug":"提示词三-它怎么扩展","link":"#提示词三-它怎么扩展","children":[]}]},{"level":2,"title":"跑完之后我对 Hermes 的认知","slug":"跑完之后我对-hermes-的认知","link":"#跑完之后我对-hermes-的认知","children":[]},{"level":2,"title":"先停一下，回到官方文档","slug":"先停一下-回到官方文档","link":"#先停一下-回到官方文档","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级老项目改造实战/24｜建立学习框架：用AI快速拆解学习HermesAgent.md","filePath":"ClaudeCode企业级老项目改造实战/24｜建立学习框架：用AI快速拆解学习HermesAgent.md","lastUpdated":1795530109000}'),i={name:"ClaudeCode企业级老项目改造实战/24｜建立学习框架：用AI快速拆解学习HermesAgent.md"};function p(t,e,o,r,d,h){return s(),l("div",null,[...e[0]||(e[0]=[n(`<h1 id="_24-建立学习框架-用ai快速拆解学习hermesagent" tabindex="-1">24 | 建立学习框架：用AI快速拆解学习HermesAgent <a class="header-anchor" href="#_24-建立学习框架-用ai快速拆解学习hermesagent" aria-label="Permalink to &quot;24 | 建立学习框架：用AI快速拆解学习HermesAgent&quot;">​</a></h1><p>你好，我是 Robert。</p><p>从这一讲开始，我们进入第六部分。这一部分要做的事情和前面几部分都不太一样。前面我们改造的是公司内部维护的老项目，代码是我们的、bug 是我们的、方向也是我们定的。但还有另一种同样常见的场景：接到一个需求，要基于一个开源项目去实现。比如运维同学做内部巡检平台，先看 Prometheus 生态有什么现成的；后端同学给业务接工作流引擎，先看Temporal、Airflow 哪个能用；算法同学做 RAG 应用，先看 LlamaIndex 还是 Dify 更合适……都是先看看开源里有没有现成的，再基于它二次开发，这是工程师的标准动作。</p><p>所以在第六部分，我会用给一个开源项目添加“基于 Hermes Agent 实现的 7×24 不间断跑混沌测试的 AI 系统”的例子，来讲解如何通过 Claude Code 对开源的老项目进行二次开发（添加功能）。这个自动化测试系统的功能主要包括：自动起集群、自动注入故障、自动调多语言SDK 跑测试、自动收集日志、自动出报告。</p><ul><li>这个项目有两篇关于「基于 AI 的自动化测试」的资料你可以看一下：<a href="https://robustmq.com/zh/Blogs/95https://robustmq.com/zh/Blogs/84" target="_blank" rel="noreferrer">https://robustmq.com/zh/Blogs/95https://robustmq.com/zh/Blogs/84</a></li></ul><p>当然，我们依旧假设我们对 Hermes Agent 一点都不了解，下面开始。</p><p>Hermes Agent 是一个开源的自托管 AI Agent 控制平面，我之前听过这个项目，但没有真正用过。这就是我们的任务的起点。顺带说一句，Hermes 还很新，你公开搜不到太多企业落地案例，这恰好是这一部分的价值，我们一起摸出一条路。AI 时代最值钱的能力之一，就是在没有现成先例的时候，基于 AI 快速摸出一条能走通的路。</p><h2 id="方法论-让-ai-帮你建立顶层认知" tabindex="-1">方法论：让 AI 帮你建立顶层认知 <a class="header-anchor" href="#方法论-让-ai-帮你建立顶层认知" aria-label="Permalink to &quot;方法论：让 AI 帮你建立顶层认知&quot;">​</a></h2><h3 id="学习前的一些想法" tabindex="-1">学习前的一些想法 <a class="header-anchor" href="#学习前的一些想法" aria-label="Permalink to &quot;学习前的一些想法&quot;">​</a></h3><p>我接到这个任务的第一反应是：Hermes Agent 是什么？我要怎么用它来实现我们这个 7×24不间断跑混沌测试的 AI 系统？所以我准备先去学习一下 Hermes Agent。</p><p>学习方式，我有两个选择:</p><ol><li><p>通过 Claude Code 辅助学习。我近期已经习惯了让 Claude Code 帮我总结，但我个人的经验是，从头学一个大的东西（比如 OpenClaw 原理、Hermes Agent 等），用 ClaudeCode 学下来并不是那么好。这里说的“好”是系统性，AI 给你的认知是片段化的，不够成体系。</p></li><li><p>系统化学习。直接找官方系统化的资料来学。我让 Claude Code 给我推荐了系统化的学习资料，找到了 hermesagent.org.cn/docs 这一份，内容很系统，挺合适。</p></li></ol><p>所以我个人的习惯是这样：Claude Code 帮我快速建立认知、总结核心要点，然后通过系统化资料沉下去学。</p><p>学新东西时，我还有两个自己摸出来的经验。一是要有自己的学习框架，二是学习是带着任务去的、不是大而全的学习。下面分别说说这两点。</p><h3 id="顶层认知-要有自己的拆解框架" tabindex="-1">顶层认知，要有自己的拆解框架 <a class="header-anchor" href="#顶层认知-要有自己的拆解框架" aria-label="Permalink to &quot;顶层认知，要有自己的拆解框架&quot;">​</a></h3><p>在我看来，让 AI 帮你建立认知，前提是你得先有一个拆解框架。</p><p>很多人用 AI 学开源项目，做法是“Claude，告诉我 Hermes 是什么”，然后拿到一坨官方话术：它是 AI Agent 平台、它支持多种扩展、它有完整的工具链。看完之后，依然不知道能拿它干什么。</p><p>问题不在 AI，在你没给 AI 一个拆解框架。工程师拿到一个陌生开源项目要建立的顶层认知，不是 AI 自己能猜出来的，它是过去十年踩坑沉淀出来的判断维度。这个框架是你的能力，不是 AI 的能力。AI 的能力是，你给好框架之后，它能把框架填得又快又准。</p><p>我自己的拆解框架是这四个维度:</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/24/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/24/1.png" alt=""></a></p><ol><li><p>它是什么，定位和边界。它解决什么问题、不解决什么问题、和我熟悉的同类工具是什么关系。这一条决定我要不要继续往下看。</p></li><li><p>它能做什么，原生能力清单。自带哪些能力、不写一行代码就能用的有哪些、覆盖范围多深。这一条决定我能白嫖多少。</p></li><li><p>它怎么扩展，扩展点的形状。它的扩展机制是什么（插件、Skill、Hook 还是别的）、扩展的边界在哪、扩展的开发范式长什么样。这一条决定我自己要写的部分长什么样。</p></li><li><p>它的内部机制，关键运行时。它怎么跑起来、状态怎么管、对外的接入面有哪些。这一条决定我能不能预判它在生产环境的表现。</p></li></ol><p>这四个维度组合起来，就是一个工程师对陌生开源项目应该建立的最小完备认知。少了哪一块，要么用不起来，要么用错。</p><h3 id="带着任务去问-而不是裸问" tabindex="-1">带着任务去问，而不是裸问 <a class="header-anchor" href="#带着任务去问-而不是裸问" aria-label="Permalink to &quot;带着任务去问，而不是裸问&quot;">​</a></h3><p>光有框架还不够。同样是问 “Hermes 怎么扩展”，不带任务问和带着任务问，得到的答案完全不一样。</p><p>不带任务问，AI 会给你一份 Hermes 扩展机制大全，所有扩展点、所有 API、所有可能的玩法，看完之后你依然不知道哪个对你有用。带着任务问，AI 会过滤掉和你任务无关的部分，只告诉你“对你这个场景，应该用哪个扩展点，因为……”。这才是工程师真正需要的认知。</p><p>所以下面三个提示词，每一个都要带着“自动化测试 Agent”这个具体任务。让 AI 拿着这个任务去过滤资料、去筛选回答、去给出建议。</p><h2 id="三个提示词-摸清楚-hermes-大体框架" tabindex="-1">三个提示词，摸清楚 Hermes 大体框架 <a class="header-anchor" href="#三个提示词-摸清楚-hermes-大体框架" aria-label="Permalink to &quot;三个提示词，摸清楚 Hermes 大体框架&quot;">​</a></h2><p>下面三个提示词，对应前面四个维度。我把“它是什么”和“它的内部机制”合在一个提示词里了，因为这两块在 Hermes 这种项目里连着讲清楚最自然。</p><p>三个提示词都丢给 Claude Code，让它在 Hermes 仓库里跑。</p><h3 id="提示词一-它是什么-它的内部机制" tabindex="-1">提示词一：它是什么 + 它的内部机制 <a class="header-anchor" href="#提示词一-它是什么-它的内部机制" aria-label="Permalink to &quot;提示词一：它是什么 + 它的内部机制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你现在在 Hermes 这个开源项目的目录下。我刚接到一个公司内的任务:</span></span>
<span class="line"><span>要基于 Hermes 做一个 7×24 跑混沌测试的 AI Agent，功能包括:</span></span>
<span class="line"><span>自动起集群、注入故障、调多语言 SDK 跑测试、收集日志、生成报告、</span></span></code></pre></div><ul><li>通过飞书通知团队。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请你读 README、docs/architecture.md 和 src 顶层目录结构，告诉我:</span></span>
<span class="line"><span>1. Hermes 的核心定位是什么。一句话说清楚。</span></span>
<span class="line"><span>2. Hermes 的核心抽象有哪些。每个抽象用一句话解释它的作用。</span></span>
<span class="line"><span>3. Hermes 不解决什么问题。它的设计边界在哪。</span></span>
<span class="line"><span>4. Hermes 是怎么跑起来的。进程模型、配置加载、状态管理大致是什么样。</span></span>
<span class="line"><span>5. 结合我接到的任务，Hermes 的定位是不是和我的需求方向一致。有没有明显的不匹配。</span></span></code></pre></div><ul><li>不要复述官方话术。用你判断后的结论来回答。</li></ul><p>读完这个提示词的输出，我应该能回答这几个问题：Hermes 是不是适合做我这个任务，它的核心抽象有哪些是我会直接用到的，它的运行时模型对我的部署方案有什么影响。</p><p>Claude Code 跑完这个提示词，我拿到这些关键信息。</p><ol><li><p>核心定位：有学习能力的通用 AI 工作台，把 LLM、工具调用、跨平台消息、定时任务封装成可以长期运行的 Agent 基础设施。</p></li><li><p>核心抽象：AI Agent（对话循环）、SessionDB（SQLite + FTS5 会话存储）、Tools（自动发现的工具注册表）、Skills（Markdown 写的过程记忆）、Delegate（子 Agent 隔离调度）、Cron（定时触发）、Gateway（多平台消息路由）、Terminal Backends（本地 / Docker /SSH / Modal 等执行环境）。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行时：通常两个长期进程（hermes CLI 和 hermes gateway 网关），通过 SQLite</span></span>
<span class="line"><span>WAL 共享状态；子 Agent 是同进程线程；配置走 ~/.hermes/config.yaml，API Key</span></span>
<span class="line"><span>单独放 .env。</span></span></code></pre></div><p>更让我意外的是：</p><ol start="4"><li>不解决什么问题：不是测试框架（没有 assertion / fixture / test suite 概念）；不是可观测性</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平台（日志只到 agent.log，没有结构化指标和告警）；不是集群编排器（Terminal</span></span></code></pre></div><ul><li>backend 只是给你一个 shell）；不是报告生成引擎（没有结构化报告模板）；也没有任何故</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>障注入能力（tools/ 里没有 chaos engineering 相关实现）；默认还是 human-in-the-loop</span></span></code></pre></div><ul><li>模式（7×24 无人值守需要大量 allowlist 配置）。</li></ul><p>在我看来，它不解决什么问题，比它能做什么更值钱。这一段告诉我，我接下来要写的核心，正好填在这些“它不做”的位置上：故障注入、结构化报告、跨会话状态、无人值守的 allowlist配置。</p><p>结论：方向是对的，但 Hermes 是骨架，不是答案。我要做的是在它给我的扩展点上，把它不做的那些事补齐。</p><h3 id="提示词二-它能做什么" tabindex="-1">提示词二：它能做什么 <a class="header-anchor" href="#提示词二-它能做什么" aria-label="Permalink to &quot;提示词二：它能做什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>继续。我的任务需要这些能力，请对照 Hermes 现有功能，</span></span>
<span class="line"><span>告诉我每一项能不能直接用、用哪个特性、还需要我自己实现什么:</span></span>
<span class="line"><span>1. 定时触发(每 2 小时跑一次基础场景、每天凌晨跑全量场景)</span></span>
<span class="line"><span>2. 调用工具函数(起集群、注入故障、跑客户端、收日志、出报告)</span></span>
<span class="line"><span>3. 在多轮调用之间共享状态(集群信息、测试进度)</span></span>
<span class="line"><span>4. 生成结构化报告(JSON + Markdown)</span></span>
<span class="line"><span>5. 通过飞书发通知(测试失败、报告生成完毕)</span></span>
<span class="line"><span>6. 手动触发(开发期间针对性验证某个场景)</span></span>
<span class="line"><span>7. LLM 调用循环(多轮 tool use、错误重试、token 管理)</span></span>
<span class="line"><span>输出格式:每一项分别说，Hermes 直接支持哪些、半支持哪些(需要简单配置)、</span></span>
<span class="line"><span>完全不支持哪些(需要我自己写)。</span></span></code></pre></div><ul><li>最后给我一个总结，我自己要写的工程量大概有多大。</li></ul><p>这个提示词的关键设计是，我把任务里需要的能力一条一条列出来，让 AI 拿着我的清单去对照 Hermes 的能力。</p><p>不带这个清单去问 Hermes 能做什么，得到的会是它所有能力的罗列；带着这个清单去问，得到的是对我有用的能力筛选。</p><p>跑完之后我大概拿到这样的判断：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/24/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/24/2.png" alt=""></a></p><p>结论：我自己要写的核心收敛到几个工具函数。Hermes 的白嫖额度比我预估的高，真正的工程量大概 600-800 行 Python，集中在故障注入和报告生成两件事。</p><p>这一轮跑完，有一件让我意外的事：结构化报告这件事，不能交给 LLM 写。Claude Code 直接告诉我，如果让 LLM 直接生成 JSON，字段名会飘、嵌套层级会乱，任何下游程序解析都会踩坑。结构化的东西用代码生成，叙述性的东西交给 LLM，这个分工是我接下来设计 Tool时的一条硬规则。</p><p>这个判断非常重要。它直接决定了 25 讲拆需求的时候，我要拆到的颗粒度只到工具函数级别就够了，不用从零规划一个 Agent 框架。</p><h3 id="提示词三-它怎么扩展" tabindex="-1">提示词三：它怎么扩展 <a class="header-anchor" href="#提示词三-它怎么扩展" aria-label="Permalink to &quot;提示词三：它怎么扩展&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>继续。如果我决定用 Hermes 做这个系统，我自己要写的核心是 Skill 吗？</span></span>
<span class="line"><span>如果是，请深入读 docs/skills.md 和 examples/ 下的几个示例 Skill，告诉我:</span></span>
<span class="line"><span>1. Skill 是什么形状。目录结构、关键文件、一个最小 Skill 包含哪几样。</span></span>
<span class="line"><span>2. Skill 里的 Tool 怎么定义。函数签名、参数类型、返回值约定。</span></span>
<span class="line"><span>3. Skill 之间怎么共享状态。Memory 系统的使用范式是什么。</span></span>
<span class="line"><span>4. SKILL.md 这个文件是给谁看的、写什么内容、有没有写法约定。</span></span>
<span class="line"><span>5. 给我一个最小可行的 Skill 骨架，假设这个 Skill 只做一件事:</span></span>
<span class="line"><span>  返回当前时间。让我能判断扩展一个 Skill 的工程量大概多大。</span></span></code></pre></div><ul><li>不要泛泛而谈，我要的是能直接用来评估开发量的具体认知。</li></ul><p>这个提示词的核心是让 AI 给我“扩展点的形状”，而不是讲“扩展机制有哪些”。</p><p>注意提示词第一句的措辞：“我自己要写的核心是 Skill 吗？如果是，请告诉我……”。我特意没有把“核心是 Skill”写成肯定句，而是留出反问的空间。带任务问还不够，带任务问 + 给 AI 留反问的余地，才是更高级的姿势。AI 拿到一个肯定句会顺着你说，拿到一个疑问句才有空间纠正你的预设。</p><p>事实证明这个余地留对了。Claude Code 跑完后给我一个反认知的纠正：我以为我要写的核心是 Skill，实际上我要写的核心是 Tool。</p><p>Skill 不能定义新的 Tool，Skill 只是 Tool 的“使用说明书”。三者的分工长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tool 在 tools/*.py 用 Python 写，通过 registry.register() 注册。</span></span>
<span class="line"><span>Skill 在 skills/*/SKILL.md 用 Markdown 写，告诉 LLM 什么时候调哪个 Tool、按什么</span></span></code></pre></div><ul><li>顺序调。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill 目录下的 scripts/*.py 是普通辅助脚本，不是 Tool，Agent 通过 Terminal 工具调</span></span></code></pre></div><ul><li>用它们。</li></ul><p>这个纠正改变了我对工程量的判断。Skill 写一份 Markdown 几小时就够，真正的工作量在Tool 的 Python 实现。如果我一开始就按“写一个大的 Skill”去拆需求，最后会发现 Skill 里没法装下任何业务逻辑，绕一圈才回到 Tool 上。这种走回头路在工程上是可以避免的，前提是你要在问 AI 时留出反问的余地。</p><h2 id="跑完之后我对-hermes-的认知" tabindex="-1">跑完之后我对 Hermes 的认知 <a class="header-anchor" href="#跑完之后我对-hermes-的认知" aria-label="Permalink to &quot;跑完之后我对 Hermes 的认知&quot;">​</a></h2><p>三个提示词跑完，我对 Hermes 的认知大概是这样：</p><ol><li><p>它的定位：自托管的 AI Agent 控制平面。LLM 调用、多通道接入、定时触发、跨会话记忆、Skill 扩展，这些通用能力它都给你解决了。它的核心价值是把 Agent 工程里所有“重复的脏活”打包好，让你只关心你的业务逻辑。</p></li><li><p>它能给我什么：Cron 触发、Gateway 多通道（飞书原生支持）、Memory 跨会话状态、CLI手动触发、Delegate 子 Agent 并发、AI Agent 的工具调用循环和重试退避，这六样我直接拿来用，不写一行代码。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要写什么：几个 Tool（Python，注册到 tools/），包括起集群、注入故障、跑客户端、</span></span>
<span class="line"><span>收日志、出报告这几个工具函数；一份 SKILL.md（Markdown，放在 skills/chaos-</span></span>
<span class="line"><span>testing/），告诉 LLM 什么时候按什么顺序调这些 Tool；一份 Cron 配置定义两条定时任</span></span></code></pre></div><ul><li>务；一份 Gateway 配置接入飞书。</li></ul><ol start="4"><li>工程量：核心 600-800 行 Python，集中在 chaos_tool / cluster_tool / report_tool 三个工具上。Skill 是 Markdown，几小时就够；Cron 和 Gateway 是配置，纯参数。</li></ol><p>把这份认知画成一张边界图，左右一目了然。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/24/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E8%80%81%E9%A1%B9%E7%9B%AE%E6%94%B9%E9%80%A0%E5%AE%9E%E6%88%98/images/24/3.png" alt=""></a></p><p>这张图就是接下来 25 讲拆需求的起点。白嫖区不用拆，只需要拆开发区。原本一句话需求里那些模糊的“自动跑”、“自动通知”、“自动收集”全都被 Hermes 接走了，我真正要拆的是开发区里那几个 Tool 怎么写、SKILL.md 怎么把它们串起来。</p><h2 id="先停一下-回到官方文档" tabindex="-1">先停一下，回到官方文档 <a class="header-anchor" href="#先停一下-回到官方文档" aria-label="Permalink to &quot;先停一下，回到官方文档&quot;">​</a></h2><p>在 Claude Code 的帮助下，我们对 Hermes Agent 已经有了一个基础的框架认识。按我的经验，这时候就不应该再依赖 Claude Code 来学了，应该回头去看官方资料，系统化地补一遍。原因有两个：</p><ol><li>AI 给你的都是经过总结后的内容。如果一直只看这种被总结过的内容，是没法真正学会一个东西的（至少我是不行）。总结的过程会丢东西，而那些被丢掉的东西，往往就是你建立</li></ol><ul><li>体系化认知最需要的部分。</li></ul><ol start="2"><li>这时候去看文档，不需要把每一篇都搞懂。而是要带着前面建立起来的认知框架，加上“做一个自动化测试 Agent”的具体任务，两样一起去过文档。看的标准是大概看懂、大概知道有什么东西就行。</li></ol><p>为什么这个标准就够了？因为下一讲我们会拆解“自动化测试 Agent”的需求，然后带着拆出来的需求，再回头看本节的认知框架和官方文档。这样三轮叠加下来，效果是最好的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>接到一个基于开源项目做需求的任务，第一件事不是动手，是先把工具摸透。</p><p>摸透不是把项目读到能提 PR 的程度，而是建立一个够用于下一步拆需求的顶层认知。这个认知有四层：它是什么、它能做什么、它怎么扩展、它内部怎么跑。</p><p>让 AI 帮你建立认知的关键是两点：你要有自己的拆解框架，你要带着任务去问。框架决定问什么，任务决定怎么问。两个都到位，认知建立的速度会比你想象的快。</p><p>跑完今天这一讲，我手上已经有了一份对 Hermes 够用的认知。但还差一步，我还没拿这份认知去对照那句“做一个自动化测试 Agent”的需求。下一讲，我们就来做这件事，把一句话需求拆成能交付的方案。</p><p>这一套打法不是 Hermes 专用的，下次你接到任何“用某某开源项目实现某某需求”的任务，这套四维度框架和带任务问的姿势，都能直接套上去。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>回想你最近一次基于开源项目做二次开发的经历，如果重新来一次，你的“拆解框架”应该是哪几个维度？你接到任务时问 AI 的第一个问题，有没有带“任务视角”？</p><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,92)])])}const g=a(i,[["render",p]]);export{u as __pageData,g as default};
